const inp = $input.first().json;

const required = ['cliente_id', 'cliente_whatsapp', 'servicio_solicitado', 'fecha_solicitada', 'hora_solicitada', 'sede_preferida'];
const missing = required.filter(k => !inp[k]);
if (missing.length) {
  return [{ json: { _error: 'inputs_incompletos', missing, ...inp } }];
}

const fecha = inp.fecha_solicitada;
const hora = inp.hora_solicitada.length === 5 ? inp.hora_solicitada + ':00' : inp.hora_solicitada;
const slot_inicio_iso = `${fecha}T${hora}-05:00`;
const slotDate = new Date(slot_inicio_iso);
if (Number.isNaN(slotDate.getTime())) {
  return [{ json: { _error: 'fecha_invalida', slot_inicio_iso } }];
}
if (slotDate < new Date()) {
  return [{ json: { _error: 'fecha_en_pasado', slot_inicio_iso } }];
}

const NULL_SENTINEL = '__NULL__';

return [{
  json: {
    cliente_id: inp.cliente_id,
    cliente_whatsapp: inp.cliente_whatsapp,
    servicio_solicitado: inp.servicio_solicitado,
    sede_preferida: inp.sede_preferida,
    genero_pref: inp.genero_terapeuta_preferido || null,
    terapeuta_preferido: inp.terapeuta_preferido || null,  // string nombre opcional
    fecha,
    slot_inicio_iso,
    // params simples para queryReplacement (evita expressions condicionales con '||')
    p1: inp.servicio_solicitado,
    p2: inp.sede_preferida,
    p3: inp.genero_terapeuta_preferido ? inp.genero_terapeuta_preferido : NULL_SENTINEL,
    p4: fecha,
    p5: slot_inicio_iso,
  }
}];

const ctxRow = $input.first().json;
const ctx = ctxRow.ctx || ctxRow;
const params = $('Validar inputs').first().json;

if (params._error) {
  return [{ json: { disponible: false, motivo: params._error, params } }];
}
if (!ctx.servicio) return [{ json: { disponible: false, motivo: 'servicio_no_encontrado', params } }];
if (!ctx.sede)     return [{ json: { disponible: false, motivo: 'sede_no_encontrada', params } }];
if (!ctx.candidatos || ctx.candidatos.length === 0) {
  return [{ json: { disponible: false, motivo: 'sin_terapeutas', params, sede: ctx.sede, servicio: ctx.servicio } }];
}

const slotIni = new Date(params.slot_inicio_iso);
const slotFin = new Date(slotIni.getTime() + ctx.servicio.duracion_minutos * 60_000);
const DIAS = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];

// Timezone-safe: trabaja con la fecha y hora de Bogotá derivadas del string ISO,
// no con Date.getDay() / getHours() que dependen del runtime timezone (n8n corre en UTC).
const fechaBogota = params.fecha;  // "2026-05-09"
const horaInicioBogota = params.slot_inicio_iso.split('T')[1].substring(0, 5);  // "20:00"
const [diaY, diaM, diaD] = fechaBogota.split('-').map(Number);
const refDate = new Date(Date.UTC(diaY, diaM - 1, diaD, 12));
const diaSemana = DIAS[refDate.getUTCDay()];  // sábado, domingo, etc.
const [hI, mI] = horaInicioBogota.split(':').map(Number);
const slotMinIni = hI * 60 + mI;
const slotMinFin = slotMinIni + ctx.servicio.duracion_minutos;

function dentroHorario(hb) {
  const franjas = (hb || {})[diaSemana] || [];
  if (!franjas.length) return false;
  return franjas.some(({inicio, fin}) => {
    const [fhi, fmi] = inicio.split(':').map(Number);
    const [fhf, fmf] = fin.split(':').map(Number);
    const fIni = fhi * 60 + fmi, fFin = fhf * 60 + fmf;
    return slotMinIni >= fIni && slotMinFin <= fFin;
  });
}
function solapa(aI, aF, bI, bF) { return aI < bF && bI < aF; }

function evaluar(t) {
  if (!dentroHorario(t.horario_base)) return 'fuera_horario';
  for (const c of (ctx.citas_dia || [])) {
    if (c.terapeuta_id !== t.id && c.terapeuta_secundario_id !== t.id) continue;
    if (solapa(slotIni, slotFin, new Date(c.slot_inicio), new Date(c.slot_fin))) return 'ocupado';
  }
  for (const b of (ctx.bloqueos_dia || [])) {
    const aplica = !b.terapeuta_id || b.terapeuta_id === t.id;
    if (!aplica) continue;
    if (solapa(slotIni, slotFin, new Date(b.inicio), new Date(b.fin))) return 'bloqueo';
  }
  return 'ok';
}

// Si hay terapeuta_preferido, intentar match por nombre (case-insensitive, partial)
let preferida = null;
if (params.terapeuta_preferido) {
  const buscar = params.terapeuta_preferido.toLowerCase();
  preferida = ctx.candidatos.find(c => c.nombre.toLowerCase().includes(buscar));
}

const baseRet = {
  servicio: ctx.servicio,
  sede: ctx.sede,
  slot_inicio: slotIni.toISOString(),
  slot_fin: slotFin.toISOString(),
  cliente_id: params.cliente_id,
  cliente_whatsapp: params.cliente_whatsapp,
  servicio_nombre: params.servicio_solicitado,
};

// Caso 1: terapeuta preferida especificada
if (preferida) {
  const estado = evaluar(preferida);
  if (estado === 'ok') {
    return [{ json: { ...baseRet, disponible: true, motivo: 'ok_preferida', terapeuta: preferida } }];
  }
  // Buscar alternativas (otras candidatas disponibles ese mismo slot)
  const alternativas = ctx.candidatos
    .filter(t => t.id !== preferida.id && evaluar(t) === 'ok')
    .map(t => ({ id: t.id, nombre: t.nombre, genero: t.genero }));
  return [{ json: {
    ...baseRet,
    disponible: false,
    motivo: 'preferida_no_disponible',
    preferida: { id: preferida.id, nombre: preferida.nombre },
    preferida_motivo: estado,
    alternativas,
    params,
  }}];
}

// Caso 2: sin preferencia, primer disponible
for (const t of ctx.candidatos) {
  if (evaluar(t) === 'ok') {
    return [{ json: { ...baseRet, disponible: true, motivo: 'ok', terapeuta: t } }];
  }
}

// Caso 3: ninguno disponible — listar candidatos para mostrar en alerta admin
return [{ json: {
  disponible: false,
  motivo: 'sin_disponibilidad',
  candidatos_evaluados: ctx.candidatos.length,
  params, sede: ctx.sede, servicio: ctx.servicio,
}}];

