const cita = $input.first().json;
const upstream = $('Buscar disponibilidad').first().json;

const fecha = new Date(cita.slot_inicio).toLocaleString('es-CO', {
  weekday: 'long', day: 'numeric', month: 'long',
  hour: '2-digit', minute: '2-digit',
  timeZone: 'America/Bogota',
});
const precio = Number(upstream.servicio.precio_cop).toLocaleString('es-CO');

const text = `✨ *Reserva confirmada — Zoe Tantric SPA*

📅 ${fecha}
💆 ${upstream.servicio_nombre} (${upstream.servicio.duracion_minutos} min)
👤 Terapeuta: ${upstream.terapeuta.nombre}
📍 ${upstream.sede.nombre}

💰 Total: $${precio} COP
💳 Pagas en sitio: efectivo, tarjeta o transferencia QR.

Recibirás un código de validación 30 minutos después de iniciada tu cita.
¿Necesitas mover o cancelar? Escríbenos por aquí.`;

const adminText = `🆕 Nueva reserva
• Cita: ${cita.id}
• Cliente: ${upstream.cliente_whatsapp}
• ${upstream.servicio_nombre} con ${upstream.terapeuta.nombre}
• ${fecha}
• Total $${precio}`;

return [{
  json: {
    cita_id: cita.id,
    cliente_whatsapp: upstream.cliente_whatsapp,
    text_cliente: text,
    text_admin: adminText,
  }
}];

const r = $input.first().json;
const params = r.params || $('Validar inputs').first().json;

let text;
let textAdmin = null;

switch (r.motivo) {
  case 'inputs_incompletos':
    text = `Para agendar necesito: servicio, fecha, hora y sede. ¿Me los puedes pasar de nuevo?`;
    break;
  case 'fecha_en_pasado':
    text = `La fecha que me diste ya pasó. ¿Podemos elegir una fecha futura?`;
    break;
  case 'fecha_invalida':
    text = `No pude entender la fecha/hora. ¿Me la puedes escribir tipo "viernes 9 de mayo a las 8 pm"?`;
    break;
  case 'servicio_no_encontrado':
    text = `Ese servicio no lo encontré en el catálogo. ¿Quieres que te lo liste de nuevo?`;
    break;
  case 'sede_no_encontrada':
    text = `No reconocí la sede "${params.sede_preferida}". Tenemos *Bogotá* y *Cajicá*.`;
    break;
  case 'sin_terapeutas':
    text = `No tengo terapeutas habilitados para ${params.servicio_solicitado} en ${r.sede?.nombre || params.sede_preferida}. ¿Quieres probar otra sede o servicio?`;
    break;
  case 'preferida_no_disponible':
    {
      const altLista = (r.alternativas || []).slice(0, 3).map(a => `• ${a.nombre}`).join('\n');
      if (r.alternativas && r.alternativas.length > 0) {
        text = `${r.preferida.nombre} no está disponible a esa hora. Pero sí tengo a esta(s) terapeuta(s) libre(s):\n\n${altLista}\n\n¿Te sirve alguna?`;
      } else {
        text = `${r.preferida.nombre} no está disponible a esa hora, y tampoco tengo otras terapeutas libres en ese horario. ¿Probamos otra hora?`;
      }
      textAdmin = `⚠️ Cliente ${params.cliente_whatsapp} pidió a ${r.preferida.nombre} pero no estaba disponible. Alternativas ofrecidas: ${(r.alternativas || []).map(a => a.nombre).join(', ') || 'ninguna'}`;
    }
    break;
  case 'sin_disponibilidad':
    text = `No tengo disponibilidad para esa hora exacta. ¿Te sirve más temprano o más tarde el mismo día? También podemos buscar al día siguiente.`;
    break;
  default:
    text = `Algo no salió bien al intentar agendar (${r.motivo}). Una persona del equipo te contacta en breve.`;
}

if (!textAdmin) {
  textAdmin = `⚠️ Reserva fallida\n• Cliente: ${params.cliente_whatsapp || 'n/a'}\n• Motivo: ${r.motivo}\n• Pidió: ${params.servicio_solicitado || '?'} en ${params.sede_preferida || '?'} ${params.fecha || '?'} ${params.slot_inicio_iso ? params.slot_inicio_iso.split('T')[1].substring(0,5) : ''}`;
}

return [{
  json: {
    cliente_whatsapp: params.cliente_whatsapp,
    text_cliente: text,
    text_admin: textAdmin,
    notificar_admin: ['sin_disponibilidad', 'sin_terapeutas', 'preferida_no_disponible'].includes(r.motivo),
    motivo: r.motivo,
  }
}];

